        // - Case 3: [A-F]
        // - otherwise not supported
        unchecked {
            if (value > 47 && value < 58) value -= 48;
            else if (value > 96 && value < 103) value -= 87;
            else if (value > 64 && value < 71) value -= 55;
            else return type(uint8).max;
        }

        return value;
    }

    /**
     * @dev Escape special characters in JSON strings. This can be useful to prevent JSON injection in NFT metadata.
     *
     * WARNING: This function should only be used in double quoted JSON strings. Single quotes are not escaped.
     *
     * NOTE: This function escapes backslashes (including those in \uXXXX sequences) and the characters in ranges
     * defined in section 2.5 of RFC-4627 (U+0000 to U+001F, U+0022 and U+005C). All control characters in U+0000
     * to U+001F are escaped (\b, \t, \n, \f, \r use short form; others use \u00XX). ECMAScript's `JSON.parse` does
     * recover escaped unicode characters that are not in this range, but other tooling may provide different results.
     */
    function escapeJSON(string memory input) internal pure returns (string memory) {
        bytes memory buffer = bytes(input);

        // Put output at the FMP. Memory will be reserved later when we figure out the actual length of the escaped
        // string. All write are done using _unsafeWriteBytesOffset, which avoid the (expensive) length checks for
        // each character written.
        bytes memory output;
        assembly ("memory-safe") {
            output := mload(0x40)
        }
        uint256 outputLength = 0;

        for (uint256 i = 0; i < buffer.length; ++i) {
            uint8 char = uint8(bytes1(_unsafeReadBytesOffset(buffer, i)));
            if (((SPECIAL_CHARS_LOOKUP & (1 << char)) != 0)) {
                _unsafeWriteBytesOffset(output, outputLength++, "\\");
                if (char == 0x08) _unsafeWriteBytesOffset(output, outputLength++, "b");
                else if (char == 0x09) _unsafeWriteBytesOffset(output, outputLength++, "t");
                else if (char == 0x0a) _unsafeWriteBytesOffset(output, outputLength++, "n");
                else if (char == 0x0c) _unsafeWriteBytesOffset(output, outputLength++, "f");
                else if (char == 0x0d) _unsafeWriteBytesOffset(output, outputLength++, "r");
                else if (char == 0x5c) _unsafeWriteBytesOffset(output, outputLength++, "\\");
                else if (char == 0x22) {
                    // solhint-disable-next-line quotes
                    _unsafeWriteBytesOffset(output, outputLength++, '"');
                } else {
                    // U+0000 to U+001F without short form: output \u00XX
                    _unsafeWriteBytesOffset(output, outputLength++, "u");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char >> 4]);
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char & 0x0f]);
                }
            } else {
                _unsafeWriteBytesOffset(output, outputLength++, bytes1(char));
            }
        }
        // write the actual length and reserve memory
        assembly ("memory-safe") {
            mstore(output, outputLength)
            mstore(0x40, add(output, add(outputLength, 0x20)))
        }

        return string(output);
    }

    /**
     * @dev Reads a bytes32 from a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }

    /**
     * @dev Write a bytes1 to a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeWriteBytesOffset(bytes memory buffer, uint256 offset, bytes1 value) private pure {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            mstore8(add(add(buffer, 0x20), offset), shr(248, value))
        }
    }
}

contracts/AaveV3Adapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

// Aave V3 Interface
interface IPool {
    function supply(address asset, uint256 amount, address onBehalfOf, uint16 referralCode) external;
    function withdraw(address asset, uint256 amount, address to) external returns (uint256);
}

interface IAToken is IERC20 {
    function UNDERLYING_ASSET_ADDRESS() external view returns (address);
}

/**
 * @title AaveV3Adapter
 * @notice THIS CONTRACT IS NOT USED IN THE OASIS 0G DEPLOYMENT.
 *         It is retained in the repository as a reference implementation showing
 *         how a real Aave V3 adapter WOULD look if Aave V3 were available on 0G Chain.
 *         Aave V3 is not deployed on 0G Aristotle mainnet.
 *         Use DemoYieldAdapter.sol as the active adapter until a real protocol is available.
 *
 *         Aave V3 Pool address below is for Polygon PoS — NOT for 0G Chain.
 *         Do not deploy this contract to 0G Chain with this address.
 */
contract AaveV3Adapter is Ownable {
    using SafeERC20 for IERC20;

    // Real Aave V3 Pool on Polygon PoS: 0x794a61358D6845594F94dc1DB02A252b5b4814aD
    IPool public constant AAVE_POOL = IPool(0x794a61358D6845594F94dc1DB02A252b5b4814aD);

    // Real aUSDC token on Polygon
    IAToken public immutable aToken;
    IERC20 public immutable asset;

    address public vault;

    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);

    constructor(address _asset, address _aToken) Ownable(msg.sender) {
        asset = IERC20(_asset);
        aToken = IAToken(_aToken);
        vault = msg.sender;
    }

    modifier onlyVault() {
        require(msg.sender == vault, "Only vault");
        _;
    }

    function setVault(address _vault) external onlyOwner {
        vault = _vault;
    }

    /**
     * @dev Deposit assets into REAL Aave V3
     */
    function deposit(uint256 amount) external onlyVault {
        require(amount > 0, "Amount must be > 0");

        // Transfer tokens from vault
        asset.safeTransferFrom(msg.sender, address(this), amount);

        // Approve Aave pool
        asset.approve(address(AAVE_POOL), amount);

        // Supply to REAL Aave V3
        AAVE_POOL.supply(address(asset), amount, address(this), 0);

        emit Deposited(msg.sender, amount);
    }

    /**
     * @dev Withdraw assets from REAL Aave V3
     */
    function withdraw(uint256 amount) external onlyVault {
        // Withdraw from REAL Aave V3
        uint256 withdrawn = AAVE_POOL.withdraw(address(asset), amount, msg.sender);

        emit Withdrawn(msg.sender, withdrawn);
    }

    /**
     * @dev Get balance with REAL accrued interest from Aave
     */
    function balanceOf(address user) external view returns (uint256) {
        // aTokens represent 1:1 with deposited amount + interest
        return aToken.balanceOf(address(this));
    }

    /**
     * @dev Get current REAL APY from Aave
     * Note: In production, you'd query Aave's data provider
     */
    function getCurrentAPY() external pure returns (uint256) {
        // This would query real Aave liquidity rates
        // For now, returns placeholder - real APY varies
        return 350; // Example: 3.50% (real Aave APY changes dynamically)
    }
}

contracts/DemoYieldAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./IStrategyAdapter.sol";

/**
 * @title DemoYieldAdapter
 * @author Oasis Protocol
 *
 * ╔══════════════════════════════════════════════════════════════════════════════╗
 * ║  ⚠  DEMO PLACEHOLDER — NOT A REAL YIELD-GENERATING PROTOCOL INTEGRATION  ⚠  ║
 * ║                                                                              ║
 * ║  This adapter does not connect to any external lending, staking, or yield    ║
 * ║  protocol. It simply holds tokens on behalf of the MasterVault and reports   ║
 * ║  a totalDeposited() balance.                                                 ║
 * ║                                                                              ║
 * ║  It exists so the full rebalancing flow (MasterVault → RebalanceExecutor →   ║
 * ║  DemoYieldAdapter) can be demonstrated end-to-end on 0G Aristotle mainnet    ║
 * ║  while no suitable yield protocol integration is yet available on 0G Chain.  ║
 * ║                                                                              ║
 * ║  The UI, README, and all docs label this explicitly as illustrative.         ║
 * ║  Any APY shown in the dashboard while this adapter is active is not a real   ║
 * ║  return and is not guaranteed.                                               ║
 * ║                                                                              ║
 * ║  When a real yield integration is available on 0G Chain, replace this with   ║
 * ║  a protocol-specific adapter implementing IStrategyAdapter.                  ║
 * ╚══════════════════════════════════════════════════════════════════════════════╝
 *
 * @notice Implements IStrategyAdapter for the Oasis rebalancing system on 0G Chain.
 */
contract DemoYieldAdapter is IStrategyAdapter, Ownable {
    using SafeERC20 for IERC20;

    IERC20 private immutable _asset;
    uint256 private _totalDeposited;

    event Deposited(address indexed from, uint256 amount);
    event Withdrawn(address indexed to, uint256 amount);

    constructor(address assetToken, address admin) Ownable(admin) {
        require(assetToken != address(0), "DemoYieldAdapter: zero asset");
        _asset = IERC20(assetToken);
    }

    // ─── IStrategyAdapter ────────────────────────────────────────────────────────

    /**
     * @notice Receive tokens from the vault. MasterVault calls transferToAdapter()
     *         which does safeTransfer here first, then this deposit() records it.
     *         In a real adapter, this would supply tokens to a lending protocol.
     */
    function deposit(uint256 amount) external override onlyOwner {
        require(amount > 0, "DemoYieldAdapter: zero amount");
        _totalDeposited += amount;
        emit Deposited(msg.sender, amount);
    }

    /**
     * @notice Return tokens to the vault.
     *         In a real adapter, this would redeem from the lending protocol.
     */
    function withdraw(uint256 amount) external override onlyOwner {
        require(amount > 0, "DemoYieldAdapter: zero amount");
        require(_totalDeposited >= amount, "DemoYieldAdapter: insufficient balance");
        _totalDeposited -= amount;
        _asset.safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount);
    }

    function totalDeposited() external view override returns (uint256) {
        return _totalDeposited;
    }

    function adapterName() external pure override returns (string memory) {
        // DEMO: this is a placeholder, not a real protocol name
        return unicode"DemoYieldAdapter (placeholder - no real yield)";
    }

    function asset() external view override returns (address) {
        return address(_asset);
    }
}

contracts/IStrategyAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title IStrategyAdapter
 * @notice Interface for yield strategy adapters in the Oasis vault system on 0G Chain.
 *         All adapters must implement this interface so the RebalanceExecutor can
 *         move funds between strategies without knowing their internal details.
 */
interface IStrategyAdapter {
    /**
     * @notice Deposit tokens into this strategy.
     * @param amount The amount of tokens to deposit.
     */
    function deposit(uint256 amount) external;

    /**
     * @notice Withdraw tokens from this strategy back to the caller.
     * @param amount The amount of tokens to withdraw.
     */
    function withdraw(uint256 amount) external;

    /**
     * @notice Returns the total token value currently held in this strategy.
     */
    function totalDeposited() external view returns (uint256);

    /**
     * @notice Human-readable name of this adapter, used in decision logs and events.
     */
    function adapterName() external view returns (string memory);

    /**
     * @notice The ERC-20 token this adapter accepts.
     */
    function asset() external view returns (address);
}

contracts/MasterVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title MasterVault
 * @author Oasis Protocol
 * @notice ERC-4626-style vault for stablecoin (USDC) deposits on 0G Chain (Aristotle, chainId 16661).
 *
 *         Architecture:
 *           User deposits USDC → MasterVault mints share tokens (ovUSDC)
 *           RebalanceExecutor (authorized via EXECUTOR_ROLE) moves funds between strategy adapters
 *           based on decisions made by AI running on 0G Compute, logged to 0G Storage.
 *
 * @dev Security: AccessControl, ReentrancyGuard, Pausable, SafeERC20.
 *      No Polygon, AggLayer, or MATIC references anywhere in this contract.
 */
contract MasterVault is ERC20, AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ─── Roles ──────────────────────────────────────────────────────────────────
    bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");
    bytes32 public constant PAUSER_ROLE   = keccak256("PAUSER_ROLE");

    // ─── State ───────────────────────────────────────────────────────────────────
    /// @notice The underlying asset accepted by this vault (e.g. USDC on 0G Chain).
    IERC20 public immutable asset;

    /// @notice Tracks total assets managed by the vault (idle + deployed in adapters).
    uint256 public totalValueLocked;

    /// @notice Strategy adapter allocations in basis points (10000 = 100%).
    mapping(address => uint256) public strategyAllocations;

    /// @notice Performance fee in basis points, charged on withdrawal (max 500 = 5%).
    ///         Fee is taken as native 0G tokens (msg.value) from the withdrawer,
    ///         since 0G Pay (https://pc.0g.ai) is a fiat/compute-credit service
    ///         and does not expose a smart-contract integration path for vault fees.
    ///         This is honestly documented; we do not claim a "0G Pay contract" integration.
    uint256 public performanceFeeBps = 50; // 0.5% default
    address public feeRecipient;

    /// @notice Counter used to generate unique request IDs for rebalance events.
    uint256 private _nextRequestId;

    // ─── Events ──────────────────────────────────────────────────────────────────
    event Deposited(address indexed user, uint256 assets, uint256 shares);
    event Withdrawn(address indexed user, uint256 assets, uint256 shares, uint256 feeCharged);
    event RebalanceRequested(uint256 indexed requestId, uint256 amount, uint256 timestamp);
    event StrategyAdded(address indexed adapter, uint256 allocationBps);
    event StrategyRemoved(address indexed adapter);
    event FeeBpsUpdated(uint256 newFeeBps);
    event FeeRecipientUpdated(address newRecipient);

    // ─── Constructor ─────────────────────────────────────────────────────────────
    /**
     * @param _asset       The ERC-20 token this vault accepts (USDC on 0G Chain).
     * @param _name        ERC-20 name for the vault share token (e.g. "Oasis USDC Vault").
     * @param _symbol      ERC-20 symbol for the share token (e.g. "ovUSDC").
     * @param _feeRecipient Address that receives withdrawal fees.
     * @param _admin       Address that is granted DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     */
    constructor(
        address _asset,
        string memory _name,
        string memory _symbol,
        address _feeRecipient,
        address _admin
    ) ERC20(_name, _symbol) {
        require(_asset != address(0), "MasterVault: zero asset");
        require(_feeRecipient != address(0), "MasterVault: zero feeRecipient");
        require(_admin != address(0), "MasterVault: zero admin");

        asset        = IERC20(_asset);
        feeRecipient = _feeRecipient;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(PAUSER_ROLE, _admin);
    }

    // ─── ERC-4626 Core ──────────────────────────────────────────────────────────

    /**
     * @notice Total assets under management: idle balance in vault + TVL deployed to adapters.
     */
    function totalAssets() public view returns (uint256) {
        return totalValueLocked;
    }

    /**
     * @notice Convert an asset amount to shares using the current exchange rate.
     */
    function convertToShares(uint256 assets_) public view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) return assets_;
        return (assets_ * supply) / totalAssets();
    }

    /**
     * @notice Convert a share amount to assets using the current exchange rate.
     */
    function convertToAssets(uint256 shares_) public view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) return shares_;
        return (shares_ * totalAssets()) / supply;
    }

    /**
     * @notice Preview how many shares would be minted for `assets` USDC deposited.
     */
    function previewDeposit(uint256 assets_) external view returns (uint256) {
        return convertToShares(assets_);
    }

    /**
     * @notice Preview how much USDC would be returned for burning `shares`.
     *         Does not account for withdrawal fee (shown separately in previewWithdrawFee).
     */
    function previewWithdraw(uint256 shares_) external view returns (uint256 assets_, uint256 fee_) {
        assets_ = convertToAssets(shares_);
        fee_    = (assets_ * performanceFeeBps) / 10000;
        assets_ = assets_ - fee_;
    }

    // ─── Deposit / Withdraw ──────────────────────────────────────────────────────

    /**
     * @notice Deposit USDC into the vault and receive share tokens.
     * @param assets   Amount of USDC to deposit.
     * @param receiver Address that receives the share tokens.
     * @return shares  The number of share tokens minted.
     */
    function deposit(uint256 assets, address receiver)
        external
        nonReentrant
        whenNotPaused
        returns (uint256 shares)
    {
        require(assets > 0, "MasterVault: zero deposit");
        require(receiver != address(0), "MasterVault: zero receiver");

        shares = convertToShares(assets);
        require(shares > 0, "MasterVault: zero shares");

        asset.safeTransferFrom(msg.sender, address(this), assets);
        totalValueLocked += assets;
        _mint(receiver, shares);

        emit Deposited(receiver, assets, shares);
    }

    /**
     * @notice Withdraw assets by burning vault shares.
     *         A performance fee (in asset tokens) is deducted and sent to feeRecipient.
     * @param shares   Number of share tokens to burn.
     * @param receiver Address that receives the net USDC.
     * @param owner    Address whose shares are burned.
     * @return assets  Net USDC transferred to receiver after fee.
     */
    function withdraw(
        uint256 shares,
        address receiver,
        address owner
    ) external nonReentrant whenNotPaused returns (uint256 assets) {
        require(shares > 0, "MasterVault: zero shares");
        require(receiver != address(0), "MasterVault: zero receiver");

        if (msg.sender != owner) {
            uint256 allowed = allowance(owner, msg.sender);
            require(allowed >= shares, "MasterVault: insufficient allowance");
            _approve(owner, msg.sender, allowed - shares);
        }

        uint256 gross = convertToAssets(shares);
        uint256 fee   = (gross * performanceFeeBps) / 10000;
        assets        = gross - fee;

        require(asset.balanceOf(address(this)) >= gross, "MasterVault: insufficient idle balance");

        _burn(owner, shares);
        totalValueLocked -= gross;

        if (fee > 0) {
            asset.safeTransfer(feeRecipient, fee);
        }
        asset.safeTransfer(receiver, assets);

        emit Withdrawn(receiver, assets, shares, fee);
    }

    // ─── Rebalance ───────────────────────────────────────────────────────────────

    /**
     * @notice Emit a RebalanceRequested event that the off-chain relayer picks up.
     *         The relayer then submits an inference job to 0G Compute
     *         (https://router-api.0g.ai/v1, API key from pc.0g.ai),
     *         logs the decision to 0G Storage (indexer: https://indexer-storage-turbo.0g.ai),
     *         and calls back via executeRebalance on RebalanceExecutor.
     * @param amount  The amount to consider for reallocation.
     * @return requestId  Unique ID for this rebalance request.
     */
    function requestRebalance(uint256 amount)
        external
        onlyRole(EXECUTOR_ROLE)
        whenNotPaused
        returns (uint256 requestId)
    {
        require(amount > 0, "MasterVault: zero amount");
        requestId = _nextRequestId++;
        emit RebalanceRequested(requestId, amount, block.timestamp);
    }

    /**
     * @notice Authorize a strategy adapter to receive funds from the vault.
     *         Called by EXECUTOR_ROLE (the RebalanceExecutor contract).
     * @param adapter      Address of the IStrategyAdapter implementation.
     * @param allocationBps Allocation in basis points (informational only; actual movement
     *                     is done by the executor's transferToAdapter call).
     */
    function setStrategyAdapter(address adapter, uint256 allocationBps)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(adapter != address(0), "MasterVault: zero adapter");
        require(allocationBps <= 10000, "MasterVault: bps > 10000");
        strategyAllocations[adapter] = allocationBps;
        emit StrategyAdded(adapter, allocationBps);
    }

    /**
     * @notice Remove a strategy adapter (set its allocation to 0).
     */
    function removeStrategyAdapter(address adapter)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        delete strategyAllocations[adapter];
        emit StrategyRemoved(adapter);
    }

    /**
     * @notice Transfer tokens to a strategy adapter (called by executor after AI decision).
     *         Only EXECUTOR_ROLE can call this.
     */
    function transferToAdapter(address adapter, uint256 amount)
        external
        onlyRole(EXECUTOR_ROLE)
        nonReentrant
        whenNotPaused
    {
        require(strategyAllocations[adapter] > 0, "MasterVault: adapter not authorized");
        require(amount > 0 && asset.balanceOf(address(this)) >= amount, "MasterVault: bad amount");
        asset.safeTransfer(adapter, amount);
    }

    /**
     * @notice Pull tokens back from a strategy adapter (called by executor on reallocation).
     */
    function recallFromAdapter(address adapter, uint256 amount)
        external
        onlyRole(EXECUTOR_ROLE)
        nonReentrant
        whenNotPaused
    {
        require(amount > 0, "MasterVault: zero amount");
        asset.safeTransferFrom(adapter, address(this), amount);
    }

    // ─── Admin ───────────────────────────────────────────────────────────────────

    function setPerformanceFeeBps(uint256 _bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_bps <= 500, "MasterVault: fee too high (max 5%)");
        performanceFeeBps = _bps;
        emit FeeBpsUpdated(_bps);
    }

    function setFeeRecipient(address _recipient) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_recipient != address(0), "MasterVault: zero address");
        feeRecipient = _recipient;
        emit FeeRecipientUpdated(_recipient);
    }

    function pause() external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    function getTVL() external view returns (uint256) { return totalValueLocked; }

    /**
     * @notice Emergency withdrawal of any token. Only DEFAULT_ADMIN_ROLE.
     */
    function emergencyWithdraw(address token, uint256 amount)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        IERC20(token).safeTransfer(msg.sender, amount);
    }
}

contracts/MockAaveAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title MockAaveAdapter
 * @dev Simulates Aave lending pool for yield generation on testnet
 * In production, this would interact with real Aave contracts
 */
contract MockAaveAdapter {
    using SafeERC20 for IERC20;

    // Track deposits per user
    mapping(address => uint256) public deposits;

    // Mock APY: 5% annual (stored as basis points)
    uint256 public constant MOCK_APY = 500; // 5.00%

    // Track last update time for interest calculation
    mapping(address => uint256) public lastUpdateTime;

    IERC20 public immutable asset;

    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);

    constructor(address _asset) {
        asset = IERC20(_asset);
    }

    /**
     * @dev Deposit assets to earn yield
     */
    function deposit(uint256 amount) external {
        require(amount > 0, "Amount must be > 0");

        // Update accrued interest before new deposit
        _updateInterest(msg.sender);

        // Transfer tokens from user
        asset.safeTransferFrom(msg.sender, address(this), amount);

        deposits[msg.sender] += amount;
        lastUpdateTime[msg.sender] = block.timestamp;

        emit Deposited(msg.sender, amount);
    }

    /**
     * @dev Withdraw assets plus earned interest
     */
    function withdraw(uint256 amount) external {
        _updateInterest(msg.sender);

        require(deposits[msg.sender] >= amount, "Insufficient balance");

        deposits[msg.sender] -= amount;
        asset.safeTransfer(msg.sender, amount);

        emit Withdrawn(msg.sender, amount);
    }

    /**
     * @dev Get total balance including accrued interest
     */
    function balanceOf(address user) external view returns (uint256) {
        return deposits[user] + _calculateInterest(user);
    }

    /**
     * @dev Calculate accrued interest (simplified)
     * In production, this would use Aave's rate model
     */
    function _calculateInterest(address user) internal view returns (uint256) {
        if (deposits[user] == 0) return 0;

        uint256 timeElapsed = block.timestamp - lastUpdateTime[user];
        // Interest = principal * APY * time / (365 days * 10000 basis points)
        return (deposits[user] * MOCK_APY * timeElapsed) / (365 days * 10000);
    }

    /**
     * @dev Update user's balance with accrued interest
     */
    function _updateInterest(address user) internal {
        uint256 interest = _calculateInterest(user);
        if (interest > 0) {
            deposits[user] += interest;
        }
        lastUpdateTime[user] = block.timestamp;
    }

    /**
     * @dev Get current APY
     */
    function getCurrentAPY() external pure returns (uint256) {
        return MOCK_APY; // Returns 500 = 5.00%
    }
}

