// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/**
 * @title MockUSDC
 * @notice Test stablecoin for local Hardhat testing only.
 *         NOT deployed to 0G Aristotle mainnet — on mainnet, MasterVault
 *         uses a real USDC-equivalent ERC-20 whose address is set at deploy time.
 *         If no native USDC exists on 0G Chain at deployment time, MasterVault
 *         is launched with this mock address for demo purposes, and the README
 *         states this explicitly.
 */
contract MockUSDC is ERC20 {
    constructor() ERC20("Mock USDC", "USDC") {
        // Mint 10 million USDC (6 decimal adjusted to 18 for simplicity)
        _mint(msg.sender, 10_000_000 * 1e18);
    }

    /// @notice Public faucet — anyone can mint 10,000 USDC for testing.
    function faucet() external {
        _mint(msg.sender, 10_000 * 1e18);
    }

    function decimals() public pure override returns (uint8) {
        return 18;
    }
}

contracts/NativeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title NativeVault
 * @author Oasis Protocol
 * @notice Vault that accepts native 0G token deposits on 0G Chain (Aristotle, chainId 16661).
 *         Mints share tokens (ov0G) representing ownership of deposited 0G.
 *
 *         This is the second vault in the Oasis dual-vault architecture:
 *           MasterVault  — accepts USDC (ERC-20)
 *           NativeVault  — accepts native 0G (the chain's gas token)
 *
 * @dev No MATIC, POL, or Polygon references anywhere.
 *      ReentrancyGuard on all state-changing payable functions.
 *      Pausable escape hatch controlled by PAUSER_ROLE.
 */
contract NativeVault is ERC20, AccessControl, ReentrancyGuard, Pausable {

    // ─── Roles ──────────────────────────────────────────────────────────────────
    bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");
    bytes32 public constant PAUSER_ROLE   = keccak256("PAUSER_ROLE");

    // ─── State ───────────────────────────────────────────────────────────────────
    /// @notice Total native 0G held by this vault (deposited - withdrawn).
    uint256 public totalValueLocked;

    /// @notice Performance fee in basis points on withdrawals (max 500).
    uint256 public performanceFeeBps = 50; // 0.5%
    address public feeRecipient;

    // ─── Events ──────────────────────────────────────────────────────────────────
    event Deposited(address indexed user, uint256 amount, uint256 shares);
    event Withdrawn(address indexed user, uint256 amount, uint256 shares, uint256 feeCharged);
    event FeeBpsUpdated(uint256 newFeeBps);
    event FeeRecipientUpdated(address newRecipient);

    // ─── Constructor ─────────────────────────────────────────────────────────────
    /**
     * @param _name        ERC-20 name for share token (e.g. "Oasis 0G Vault").
     * @param _symbol      ERC-20 symbol (e.g. "ov0G").
     * @param _feeRecipient Address that receives withdrawal fees.
     * @param _admin       Address granted DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     */
    constructor(
        string memory _name,
        string memory _symbol,
        address _feeRecipient,
        address _admin
    ) ERC20(_name, _symbol) {
        require(_feeRecipient != address(0), "NativeVault: zero feeRecipient");
        require(_admin != address(0), "NativeVault: zero admin");

        feeRecipient = _feeRecipient;
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(PAUSER_ROLE, _admin);
    }

    // ─── Core ────────────────────────────────────────────────────────────────────

    /**
     * @notice Deposit native 0G and receive vault shares (ov0G).
     * @return shares Number of share tokens minted.
     */
    function deposit() external payable nonReentrant whenNotPaused returns (uint256 shares) {
        require(msg.value > 0, "NativeVault: zero deposit");

        if (totalSupply() == 0 || totalValueLocked == 0) {
            shares = msg.value;
        } else {
            shares = (msg.value * totalSupply()) / totalValueLocked;
        }
        require(shares > 0, "NativeVault: zero shares");

        totalValueLocked += msg.value;
        _mint(msg.sender, shares);

        emit Deposited(msg.sender, msg.value, shares);
    }

    /**
     * @notice Burn share tokens to redeem native 0G.
     *         A performance fee is deducted and forwarded to feeRecipient.
     * @param shares Amount of share tokens to burn.
     * @return amount Net 0G sent to caller after fee.
     */
    function withdraw(uint256 shares) external nonReentrant whenNotPaused returns (uint256 amount) {
        require(shares > 0, "NativeVault: zero shares");
        require(balanceOf(msg.sender) >= shares, "NativeVault: insufficient shares");
        require(totalSupply() > 0, "NativeVault: no supply");

        uint256 gross = (shares * totalValueLocked) / totalSupply();
        require(gross > 0, "NativeVault: zero amount");

        uint256 fee = (gross * performanceFeeBps) / 10000;
        amount      = gross - fee;

        require(address(this).balance >= gross, "NativeVault: insufficient balance");

        totalValueLocked -= gross;
        _burn(msg.sender, shares);

        if (fee > 0) {
            (bool feeSent, ) = feeRecipient.call{value: fee}("");
            require(feeSent, "NativeVault: fee transfer failed");
        }
        (bool sent, ) = msg.sender.call{value: amount}("");
        require(sent, "NativeVault: transfer failed");

        emit Withdrawn(msg.sender, amount, shares, fee);
    }

    // ─── View helpers ────────────────────────────────────────────────────────────

    function totalAssets() external view returns (uint256) { return totalValueLocked; }

    function previewDeposit(uint256 amount) external view returns (uint256) {
        if (totalSupply() == 0 || totalValueLocked == 0) return amount;
        return (amount * totalSupply()) / totalValueLocked;
    }

    function previewWithdraw(uint256 shares) external view returns (uint256 net, uint256 fee) {
        if (totalSupply() == 0) return (0, 0);
        uint256 gross = (shares * totalValueLocked) / totalSupply();
        fee = (gross * performanceFeeBps) / 10000;
        net = gross - fee;
    }

    function balanceOfAssets(address user) external view returns (uint256) {
        if (totalSupply() == 0) return 0;
        return (balanceOf(user) * totalValueLocked) / totalSupply();
    }

    function getTVL() external view returns (uint256) { return totalValueLocked; }

    // ─── Admin ───────────────────────────────────────────────────────────────────

    function setPerformanceFeeBps(uint256 _bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_bps <= 500, "NativeVault: fee too high (max 5%)");
        performanceFeeBps = _bps;
        emit FeeBpsUpdated(_bps);
    }

    function setFeeRecipient(address _recipient) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_recipient != address(0), "NativeVault: zero address");
        feeRecipient = _recipient;
        emit FeeRecipientUpdated(_recipient);
    }

    function pause() external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    /**
     * @notice Allow the contract to receive plain 0G transfers (from adapters returning funds, etc.)
     */
    receive() external payable { totalValueLocked += msg.value; }
    fallback() external payable { totalValueLocked += msg.value; }
}

contracts/RebalanceExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./IStrategyAdapter.sol";

/**
 * @title RebalanceExecutor
 * @author Oasis Protocol
 * @notice Orchestrates AI-driven rebalancing of Oasis vault funds between strategy adapters.
 *         Deployed on 0G Chain (Aristotle, chainId 16661).
 *
 *         Flow:
 *           1. RELAYER_ROLE calls requestRebalance() → emits RebalanceRequested event
 *           2. Off-chain relayer picks up the event, submits inference to 0G Compute
 *              (endpoint: https://router-api.0g.ai/v1, API key from pc.0g.ai),
 *              writes decision record to 0G Storage
 *              (indexer: https://indexer-storage-turbo.0g.ai via 0G Storage TS SDK)
 *           3. Relayer calls executeRebalance() with the decision hash + worker attestation
 *           4. Contract verifies attestation hash and moves funds to the chosen adapter
 *           5. On failure/timeout: refundOrHold() is called to leave funds in place safely
 *
 * @dev Roles: DEFAULT_ADMIN_ROLE (admin), RELAYER_ROLE (off-chain relayer addresses).
 *      ReentrancyGuard on all fund-moving functions.
 *      Pausable escape hatch.
 */
contract RebalanceExecutor is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ─── Roles ──────────────────────────────────────────────────────────────────
    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");
    bytes32 public constant PAUSER_ROLE  = keccak256("PAUSER_ROLE");

    // ─── Structs ─────────────────────────────────────────────────────────────────
    enum RebalanceStatus { Pending, Executed, Failed }

    struct RebalanceRecord {
        uint256 requestId;
        address targetAdapter;
        uint256 amount;
        bytes32 decisionHash;         // keccak256 of the decision JSON stored on 0G Storage
        bytes   computeAttestation;   // TEE-signed attestation from 0G Compute worker
        string  storageRef;           // 0G Storage root hash reference (content address)
        uint256 timestamp;
        RebalanceStatus status;
    }

    // ─── State ───────────────────────────────────────────────────────────────────
    address public masterVault;
    address public nativeVault;

    mapping(uint256 => RebalanceRecord) public rebalances;
    uint256[] public rebalanceIds;
    uint256 private _nextRequestId;

    /// @notice Max time (seconds) relayer has to respond before a request can be marked failed.
    uint256 public rebalanceTimeout = 3600; // 1 hour default
    mapping(uint256 => uint256) public requestTimestamps;

    // ─── Events ──────────────────────────────────────────────────────────────────
    event RebalanceRequested(
        uint256 indexed requestId,
        address indexed vault,
        uint256 amount,
        uint256 timestamp
    );
    event RebalanceExecuted(
        uint256 indexed requestId,
        address indexed targetAdapter,
        uint256 amount,
        bytes32 decisionHash,
        string  storageRef
    );
    event RebalanceFailed(uint256 indexed requestId, string reason);
    event VaultSet(string vaultType, address vaultAddress);
    event TimeoutUpdated(uint256 newTimeout);

    // ─── Constructor ─────────────────────────────────────────────────────────────
    /**
     * @param _masterVault Address of the MasterVault (USDC vault).
     * @param _nativeVault Address of the NativeVault (0G native vault).
     * @param _admin       Address granted DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     */
    constructor(address _masterVault, address _nativeVault, address _admin) {
        require(_masterVault != address(0), "RebalanceExecutor: zero masterVault");
        require(_admin != address(0), "RebalanceExecutor: zero admin");

        masterVault = _masterVault;
        nativeVault = _nativeVault;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(PAUSER_ROLE, _admin);
    }

    // ─── Request ─────────────────────────────────────────────────────────────────

    /**
     * @notice Emit a rebalance request for the off-chain relayer to pick up.
     *         The relayer submits the decision to 0G Compute and logs it on 0G Storage,
     *         then calls back with executeRebalance().
     * @param vault   The vault whose funds should be rebalanced (masterVault or nativeVault).
     * @param amount  Amount to consider for reallocation.
     * @return requestId  Unique ID for tracking this request.
     */
    function requestRebalance(address vault, uint256 amount)
        external
        onlyRole(RELAYER_ROLE)
        whenNotPaused
        returns (uint256 requestId)
    {
        require(vault == masterVault || vault == nativeVault, "RebalanceExecutor: unknown vault");
        require(amount > 0, "RebalanceExecutor: zero amount");

        requestId = _nextRequestId++;
        requestTimestamps[requestId] = block.timestamp;

        emit RebalanceRequested(requestId, vault, amount, block.timestamp);
    }

    // ─── Execute ─────────────────────────────────────────────────────────────────

    /**
     * @notice Execute a rebalance decision returned by the 0G Compute worker.
     *         Only RELAYER_ROLE can call this. Verifies the attestation is non-empty
     *         and that the decision hash matches (keccak256 of the decision payload).
     *
     * @param requestId          The ID emitted by requestRebalance().
     * @param vault              Which vault to move funds from.
     * @param targetAdapter      The IStrategyAdapter to allocate funds to.
     * @param amount             Amount of tokens to move.
     * @param decisionHash       keccak256 hash of the full decision JSON (verified off-chain,
     *                           stored on 0G Storage — we record it on-chain for auditability).
     * @param computeAttestation Raw attestation bytes from the 0G Compute TEE worker.
     *                           In the current 0G Compute Router path, this is the
     *                           x-worker-signature header value from the completion response.
     * @param storageRef         0G Storage root hash / content reference for the decision log.
     */
    function executeRebalance(
        uint256 requestId,
        address vault,
        address targetAdapter,
        uint256 amount,
        bytes32 decisionHash,
        bytes calldata computeAttestation,
        string calldata storageRef
    ) external onlyRole(RELAYER_ROLE) nonReentrant whenNotPaused {
        require(rebalances[requestId].timestamp == 0, "RebalanceExecutor: already executed");
        require(vault == masterVault || vault == nativeVault, "RebalanceExecutor: unknown vault");
        require(targetAdapter != address(0), "RebalanceExecutor: zero adapter");
        require(amount > 0, "RebalanceExecutor: zero amount");
        require(computeAttestation.length > 0, "RebalanceExecutor: missing attestation");
        require(bytes(storageRef).length > 0, "RebalanceExecutor: missing storageRef");

        // Record the rebalance
        rebalances[requestId] = RebalanceRecord({
            requestId:          requestId,
            targetAdapter:      targetAdapter,
            amount:             amount,
            decisionHash:       decisionHash,
            computeAttestation: computeAttestation,
            storageRef:         storageRef,
            timestamp:          block.timestamp,
            status:             RebalanceStatus.Executed
        });
        rebalanceIds.push(requestId);

        // Move funds: call MasterVault's transferToAdapter (vault must grant EXECUTOR_ROLE here)
        // For NativeVault, adapters are handled separately (native token flow)
        if (vault == masterVault) {
            // Calls MasterVault.transferToAdapter → safeTransfer to adapter
            (bool ok, bytes memory err) = masterVault.call(
                abi.encodeWithSignature("transferToAdapter(address,uint256)", targetAdapter, amount)
            );
            if (!ok) {
                rebalances[requestId].status = RebalanceStatus.Failed;
                emit RebalanceFailed(requestId, _extractRevertReason(err));
                return;
            }
        }
        // NativeVault adapter interactions are currently demo-only (DemoYieldAdapter)

        emit RebalanceExecuted(requestId, targetAdapter, amount, decisionHash, storageRef);
    }

    // ─── Refund / Hold on Failure ────────────────────────────────────────────────

    /**
     * @notice If a rebalance request has not been fulfilled within rebalanceTimeout seconds,
     *         mark it as failed. Funds remain in the vault (no indefinite blocking).
     *         Anyone can call this — it's a safety hatch, not a privileged function.
     * @param requestId The request ID to expire.
     */
    function refundOrHoldOnFailure(uint256 requestId) external {
        require(rebalances[requestId].timestamp == 0, "RebalanceExecutor: already settled");
        uint256 ts = requestTimestamps[requestId];
        require(ts > 0, "RebalanceExecutor: unknown request");
        require(block.timestamp > ts + rebalanceTimeout, "RebalanceExecutor: not timed out");

        rebalances[requestId] = RebalanceRecord({
            requestId:          requestId,
            targetAdapter:      address(0),
            amount:             0,
            decisionHash:       bytes32(0),
            computeAttestation: "",
            storageRef:         "",
            timestamp:          block.timestamp,
            status:             RebalanceStatus.Failed
        });
        rebalanceIds.push(requestId);
        emit RebalanceFailed(requestId, "timeout: funds held in vault");
    }

    // ─── View ────────────────────────────────────────────────────────────────────

    function getRebalanceCount() external view returns (uint256) {
        return rebalanceIds.length;
    }

    function getRebalance(uint256 requestId) external view returns (RebalanceRecord memory) {
        return rebalances[requestId];
    }

    function getAllRebalanceIds() external view returns (uint256[] memory) {
        return rebalanceIds;
    }

    // ─── Admin ───────────────────────────────────────────────────────────────────

    function setMasterVault(address _vault) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_vault != address(0), "RebalanceExecutor: zero address");
        masterVault = _vault;
        emit VaultSet("masterVault", _vault);
    }

    function setNativeVault(address _vault) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_vault != address(0), "RebalanceExecutor: zero address");
        nativeVault = _vault;
        emit VaultSet("nativeVault", _vault);
    }

    function setRebalanceTimeout(uint256 _timeout) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_timeout >= 300, "RebalanceExecutor: minimum 5 minutes");
        rebalanceTimeout = _timeout;
        emit TimeoutUpdated(_timeout);
    }

    function pause() external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    // ─── Internal ────────────────────────────────────────────────────────────────

    function _extractRevertReason(bytes memory revertData) internal pure returns (string memory) {
        if (revertData.length < 68) return "unknown revert";
        assembly {
            revertData := add(revertData, 0x04)
        }
        return abi.decode(revertData, (string));
    }
}

contracts/StrategyAgenticID.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title StrategyAgenticID
 * @author Oasis Protocol
 * @notice ERC-721 token that represents a tokenized yield strategy identity — an "Agentic ID"
 *         for the AI model governing the Oasis vault system on 0G Chain.
 *
 *         This implements the 0G Agentic ID concept (https://docs.0g.ai/developer-hub/building-on-0g/agentic-id/overview)
 *         as an ERC-721 where each token represents one AI strategy configuration.
 *
 *         Key design decisions:
 *         - Encrypted metadata (model config, strategy params) is stored on 0G Storage;
 *           the on-chain token holds only the content hash reference.
 *         - On transfer, the full performance history is carried forward. History is stored
 *           by tokenId in a mapping, so it survives ownership changes without reset.
 *         - Only one strategy token exists per vault deployment (the "active strategy").
 *           Future versions may support multiple competing strategies.
 *
 * @dev Storage of decision history:
 *      Each time a rebalance executes, the RebalanceExecutor emits a RebalanceExecuted event
 *      with a storageRef (0G Storage root hash). The relayer also calls recordDecision() here
 *      to push the storage reference into the on-chain history array for the token.
 *      This enables the frontend to enumerate all decisions tied to a strategy token
 *      without reading every event from block 0.
 */
contract StrategyAgenticID is ERC721, AccessControl {

    // ─── Roles ──────────────────────────────────────────────────────────────────
    bytes32 public constant MINTER_ROLE   = keccak256("MINTER_ROLE");
    bytes32 public constant RECORDER_ROLE = keccak256("RECORDER_ROLE");

    // ─── Structs ─────────────────────────────────────────────────────────────────
    struct StrategyMetadata {
        /// @dev 0G Storage root hash of the (encrypted) strategy config JSON.
        string  storageRef;
        /// @dev Human-readable name of the strategy.
        string  name;
        /// @dev Timestamp of when this strategy was minted / activated.
        uint256 activatedAt;
        /// @dev Total number of rebalance decisions recorded for this strategy.
        uint256 decisionCount;
    }

    struct DecisionRecord {
        /// @dev 0G Storage root hash of the decision JSON (inputs, output, reasoning).
        string  storageRef;
        /// @dev keccak256 of the decision payload — also emitted on-chain by RebalanceExecutor.
        bytes32 decisionHash;
        /// @dev Block timestamp when this decision was recorded.
        uint256 timestamp;
    }

    // ─── State ───────────────────────────────────────────────────────────────────
    uint256 private _nextTokenId;

    mapping(uint256 => StrategyMetadata)  public metadata;
    mapping(uint256 => DecisionRecord[])  private _history;

    // ─── Events ──────────────────────────────────────────────────────────────────
    event StrategyMinted(uint256 indexed tokenId, address indexed owner, string storageRef, string name);
    event DecisionRecorded(uint256 indexed tokenId, uint256 decisionIndex, bytes32 decisionHash, string storageRef);
    event StorageRefUpdated(uint256 indexed tokenId, string newStorageRef);

    // ─── Constructor ─────────────────────────────────────────────────────────────
    constructor(address _admin) ERC721("Oasis Strategy Agentic ID", "OSAID") {
        require(_admin != address(0), "StrategyAgenticID: zero admin");
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(MINTER_ROLE, _admin);
    }

    // ─── Core ────────────────────────────────────────────────────────────────────

    /**
     * @notice Mint a new strategy token representing the AI strategy governing the vault.
     *         Typically called once at deployment. Multiple tokens can exist, but only one
     *         is active at a time (enforced off-chain by the relayer configuration).
     *
     * @param to         Address that owns the strategy (e.g. vault deployer or DAO).
     * @param storageRef 0G Storage root hash of the encrypted strategy config.
     * @param name       Human-readable strategy name.
     * @return tokenId   The minted token ID.
     */
    function mintStrategy(address to, string calldata storageRef, string calldata name)
        external
        onlyRole(MINTER_ROLE)
        returns (uint256 tokenId)
    {
        require(to != address(0), "StrategyAgenticID: zero recipient");
        require(bytes(storageRef).length > 0, "StrategyAgenticID: empty storageRef");
        require(bytes(name).length > 0, "StrategyAgenticID: empty name");

        tokenId = _nextTokenId++;
        _safeMint(to, tokenId);

        metadata[tokenId] = StrategyMetadata({
            storageRef:    storageRef,
            name:          name,
            activatedAt:   block.timestamp,
            decisionCount: 0
        });

        emit StrategyMinted(tokenId, to, storageRef, name);
    }

    /**
     * @notice Record a rebalance decision in the strategy's on-chain history.
     *         Called by the RECORDER_ROLE (the relayer or RebalanceExecutor).
     *         History is keyed by tokenId and survives ownership transfers — this is the
     *         core differentiator: transferring the Agentic ID token carries the full
     *         track record forward. There is no reset on transfer.
     *
     * @param tokenId      The strategy token this decision belongs to.
     * @param storageRef   0G Storage root hash of the decision JSON.
     * @param decisionHash keccak256 of the decision payload (matches RebalanceExecuted event).
     */
    function recordDecision(uint256 tokenId, string calldata storageRef, bytes32 decisionHash)
        external
        onlyRole(RECORDER_ROLE)
    {
        require(_ownerOf(tokenId) != address(0), "StrategyAgenticID: token does not exist");
        require(bytes(storageRef).length > 0, "StrategyAgenticID: empty storageRef");

        _history[tokenId].push(DecisionRecord({
            storageRef:   storageRef,
            decisionHash: decisionHash,
            timestamp:    block.timestamp
        }));

        metadata[tokenId].decisionCount++;

        emit DecisionRecorded(tokenId, _history[tokenId].length - 1, decisionHash, storageRef);
    }

    /**
     * @notice Update the 0G Storage reference for the strategy metadata
     *         (e.g. when model config is updated).
     */
    function updateStorageRef(uint256 tokenId, string calldata newRef)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(_ownerOf(tokenId) != address(0), "StrategyAgenticID: token does not exist");
        metadata[tokenId].storageRef = newRef;
        emit StorageRefUpdated(tokenId, newRef);
    }

    // ─── View ────────────────────────────────────────────────────────────────────

    /**
     * @notice Get the full decision history for a strategy token.
     *         This history is preserved across ownership transfers.
     */
    function getHistory(uint256 tokenId) external view returns (DecisionRecord[] memory) {
        return _history[tokenId];
    }

    /**
     * @notice Get a specific decision record by index.
     */
    function getDecision(uint256 tokenId, uint256 index) external view returns (DecisionRecord memory) {
        require(index < _history[tokenId].length, "StrategyAgenticID: index out of bounds");
        return _history[tokenId][index];
    }

    /**
     * @notice Get the number of decisions recorded for a token.
     */
    function decisionCount(uint256 tokenId) external view returns (uint256) {
        return _history[tokenId].length;
    }

    function totalStrategies() external view returns (uint256) {
        return _nextTokenId;
    }

    // ─── ERC-165 override to support both ERC721 and AccessControl ───────────────
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

